from google.cloud import texttospeech
from typing import List, Dict, Any

def list_voices(language_code: str = None) -> List[Dict[str, Any]]:
    """Lists available voices for a given language code using Google Cloud Text-to-Speech."""
    client = texttospeech.TextToSpeechClient()
    voices = client.list_voices(language_code=language_code).voices

    voice_details = []
    for voice in voices:
        voice_details.append({
            "name": voice.name,
            "language_codes": list(voice.language_codes),
            "ssml_gender": texttospeech.SsmlVoiceGender(voice.ssml_gender).name,
            "natural_sample_rate_hertz": voice.natural_sample_rate_hertz,
        })
    return voice_details

def select_voice(language_code: str, ssml_gender: texttospeech.SsmlVoiceGender) -> texttospeech.VoiceSelectionParams:
    """Selects a voice based on language code and SSML gender."""
    return texttospeech.VoiceSelectionParams(
        language_code=language_code,
        ssml_gender=ssml_gender
    )

from google.cloud import texttospeech

def get_text_to_speech_client():
    """Provides a Google Cloud Text-to-Speech client instance."""
    return texttospeech.TextToSpeechClient()

# Example of potential centralized configuration (if needed)
def get_default_voice_params():
    return texttospeech.VoiceSelectionParams(
        language_code="en-US", 
        ssml_gender=texttospeech.SsmlVoiceGender.NEUTRAL
    )

def get_default_audio_config():
    return texttospeech.AudioConfig(
        audio_encoding=texttospeech.AudioEncoding.LINEAR16
    )

from google.cloud import texttospeech
from dataclasses import dataclass

@dataclass
class SynthesisRequest:
    text: str | None = None
    ssml: str | None = None
    language_code: str = "en-US"
    ssml_gender: texttospeech.SsmlVoiceGender = texttospeech.SsmlVoiceGender.NEUTRAL
    audio_encoding: texttospeech.AudioEncoding = texttospeech.AudioEncoding.LINEAR16

def create_synthesis_input(request: SynthesisRequest) -> texttospeech.SynthesisInput:
    if request.text:
        return texttospeech.SynthesisInput(text=request.text)
    elif request.ssml:
        return texttospeech.SynthesisInput(ssml=request.ssml)
    else:
        raise ValueError("Either 'text' or 'ssml' must be provided in SynthesisRequest.")

def create_voice_params(request: SynthesisRequest) -> texttospeech.VoiceSelectionParams:
    return texttospeech.VoiceSelectionParams(
        language_code=request.language_code,
        ssml_gender=request.ssml_gender
    )

def create_audio_config(request: SynthesisRequest) -> texttospeech.AudioConfig:
    return texttospeech.AudioConfig(
        audio_encoding=request.audio_encoding
    )

def extract_audio_content(response: texttospeech.SynthesizeSpeechResponse) -> bytes:
    return response.audio_content
